import sys

def solve(n, m, field):
    def dfs(x, y, fig_id):
        stack = [(x, y)]
        while stack:
            cx, cy = stack.pop()
            if field[cx][cy] != '.':
                continue
            field[cx][cy] = str(fig_id)
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = cx + dx, cy + dy
                if 0 <= nx < n and 0 <= ny < m and field[nx][ny] == '.':
                    stack.append((nx, ny))

    fig_id = 1
    for i in range(n):
        for j in range(m):
            if field[i][j] == '.':
                dfs(i, j, fig_id)
                fig_id += 1

    for i in range(n):
        if any(c == '.' for c in field[i]):
            print('-1')
            return

    for row in field:
        print(''.join(row))

input = sys.stdin.read().strip().split('\n')
n, m = map(int, input[0].split())
field = input[1:]
solve(n, m, field)
